import{_ as t,o as n,c as a,a3 as i}from"./chunks/framework.BlfGB29P.js";const h=JSON.parse('{"title":"ATLAS – Runtime Foundation","description":"Der aktuelle Entwicklungsstand des modularen ATLAS-Frameworks.","frontmatter":{"title":"ATLAS – Runtime Foundation","description":"Der aktuelle Entwicklungsstand des modularen ATLAS-Frameworks.","date":"2026-08-02T00:00:00.000Z","author":"UGSo Software","tags":["ATLAS","TypeScript","Architektur"]},"headers":[],"relativePath":"blog/posts/atlas-runtime-foundation.md","filePath":"blog/posts/atlas-runtime-foundation.md","lastUpdated":1792862520000}'),r={name:"blog/posts/atlas-runtime-foundation.md"};function s(l,e,o,u,d,p){return n(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="atlas-–-runtime-foundation" tabindex="-1">ATLAS – Runtime Foundation <a class="header-anchor" href="#atlas-–-runtime-foundation" aria-label="Permalink to &quot;ATLAS – Runtime Foundation&quot;">​</a></h1><p><strong>2. August 2026 · ATLAS</strong></p><p>ATLAS ist ein modulares TypeScript-Framework für wiederverwendbare Anwendungen, Plugins und Home-Assistant-nahe Werkzeuge.</p><h2 id="aktueller-stand" tabindex="-1">Aktueller Stand <a class="header-anchor" href="#aktueller-stand" aria-label="Permalink to &quot;Aktueller Stand&quot;">​</a></h2><p>Die grundlegende Repository- und Dokumentationsstruktur ist fertiggestellt.</p><p>Bereits umgesetzt sind:</p><ul><li>Monorepo mit <code>pnpm</code> Workspaces</li><li>Governance- und Architektur-Dokumente</li><li>Event- und Contract-Schicht</li><li>öffentliche Event-Verträge</li><li>Referenzimplementierung <code>DefaultEventBus</code></li><li>Tests für die grundlegenden Komponenten</li></ul><h2 id="nachster-sprint" tabindex="-1">Nächster Sprint <a class="header-anchor" href="#nachster-sprint" aria-label="Permalink to &quot;Nächster Sprint&quot;">​</a></h2><p>Der nächste Entwicklungsschritt ist:</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Sprint G2.5.3 – Runtime Foundation</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>Dabei liegt der Schwerpunkt auf:</p><ul><li>Service-Container</li><li>Dependency Injection</li><li>Service-Beschreibungen</li><li>kontrollierter Auflösung von Abhängigkeiten</li><li>stabilen Runtime-Verträgen</li></ul><h2 id="langfristiges-ziel" tabindex="-1">Langfristiges Ziel <a class="header-anchor" href="#langfristiges-ziel" aria-label="Permalink to &quot;Langfristiges Ziel&quot;">​</a></h2><p>ATLAS soll eine gemeinsame technische Grundlage für mehrere UGSo-Projekte schaffen.</p><p>Die <strong>Lovelace UV Card</strong> bleibt als späteres Projekt für UV-Index, Schutzstatus und visuelle Home-Assistant-Dashboards geplant.</p><h2 id="mehr-erfahren" tabindex="-1">Mehr erfahren <a class="header-anchor" href="#mehr-erfahren" aria-label="Permalink to &quot;Mehr erfahren&quot;">​</a></h2><p><a href="/projects/atlas/">ATLAS-Projektseite öffnen</a></p>',17)])])}const m=t(r,[["render",s]]);export{h as __pageData,m as default};
